use xiom.io;
type Recipe = {
  name: Str;
  cook_time: Int;
  tags: Set[Str];
}

type RecipeBox = {
  recipes: Map[Str, Recipe];
  by_tag: Map[Str, Vec[Str]];
}

fn RecipeBox.new() -> RecipeBox {
  return RecipeBox{ recipes: Map[Str, Recipe].new(), by_tag: Map[Str, Vec[Str]].new() };
}

fn RecipeBox.add_recipe(box: &mut RecipeBox, recipe: Recipe) {
  box.recipes.insert(recipe.name, recipe);
}

fn main() -> Int {
  let rbox: RecipeBox = RecipeBox.new();
  io.println("Ready to cook!");
  return 0;
}
